Code.Terraform:
```hcl
data "aws_caller_identity" "example_resource" {}

data "aws_iam_policy_document" "example_resource" {
  statement {
    effect = "Allow"

    principals {
      type = "Federated"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.example_resource.account_id}:oidc-provider/token.actions.githubusercontent.com"]
    }

    actions = ["sts:AssumeRoleWithWebIdentity"]

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:ORG/REPOSITORY:*"] # Restrict to this repository
    }
  }
}

resource "aws_iam_role" "example_resource" {
  name               = "example_resource"
  assume_role_policy = data.aws_iam_policy_document.example_resource.json
}
```
